levels: [undefined, {levelSize: '10%'}]
// 其他行的高度均匀分配
levelSize: undefined,
data: [
{
// 第一个单元格的宽度为 30 像素
size: 30
},
// 其他单元格的宽度均匀分配
// ...
]
},
y: {
// 第二列的宽度为矩阵宽度的 10%
levels: [undefined, {levelSize: '10%'}]
// 其他列的宽度均匀分配
levelSize: undefined,
data: [
{
// 第一个单元格的高度为 30 像素
size: 30
},
// 其他单元格的高度均匀分配
// ...
]
},
// ...
},
}

```

